        toggleExtraordinaryModule(enabled) {
            const activeCourse = Store.getActiveCourse();
            const center = activeCourse ? activeCourse.centroEducativo : (Store.data.configAcademica?.centroEducativo || 'default_center');
            const year = Store.data.configAcademica?.anioLectivo || new Date().getFullYear();
            const partial = Store.data.configAcademica?.parcialActivo || 'I Parcial';

            const current = Store.getExtraordinarySettings(center, year, partial);
            current.center_id = center;
            current.academic_year = year;
            current.partial_id = partial;
            current.enabled = enabled;

            Store.saveExtraordinarySettings(current);
            UI.toast(enabled ? 'Módulo de Actividades Extraordinarias activado' : 'Módulo de Actividades Extraordinarias desactivado', 'info');
        },
        toggleAllowAbove100(allow) {
            const activeCourse = Store.getActiveCourse();
            const center = activeCourse ? activeCourse.centroEducativo : (Store.data.configAcademica?.centroEducativo || 'default_center');
            const year = Store.data.configAcademica?.anioLectivo || new Date().getFullYear();
            const partial = Store.data.configAcademica?.parcialActivo || 'I Parcial';

            const current = Store.getExtraordinarySettings(center, year, partial);
            current.center_id = center;
            current.academic_year = year;
            current.partial_id = partial;
            current.allow_above_100 = allow;

            Store.saveExtraordinarySettings(current);
            UI.toast('Política de Nota Reportable actualizada', 'success');
        },
